param([ValidateSet('x86', 'x64')][string]$CompileArchitecture)
$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
$source = Join-Path $repoRoot '.deps/dxvk-remix'
$testDir = Join-Path $repoRoot 'work/ipc-c32-native/steam-capture'
New-Item -ItemType Directory -Force $testDir | Out-Null
if ($CompileArchitecture) {
  . (Join-Path $source 'bridge/build_common.ps1')
  SetupVS -Platform $CompileArchitecture -VcVarsVer '14.29'
  Push-Location $testDir
  try {
    & python.exe "$repoRoot/scripts/generate_capture_state_fixture.py" --source $source --output "capture-state-$CompileArchitecture.cpp"
    if ($LASTEXITCODE -ne 0) { throw 'Actual Steam capture extraction failed' }
    & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "capture-state-$CompileArchitecture.cpp" "/Fe:capture-state-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw "Steam capture compilation failed for $CompileArchitecture" }
    Assert-NativeArchitecture -Path (Join-Path $testDir "capture-state-$CompileArchitecture.exe") -Architecture $CompileArchitecture
    & ".\capture-state-$CompileArchitecture.exe"
    if ($LASTEXITCODE -ne 0) { throw "Steam capture test failed for $CompileArchitecture" }
  } finally { Pop-Location }
} else {
  foreach ($arch in @('x86', 'x64')) {
    & powershell.exe -NoProfile -File $PSCommandPath -CompileArchitecture $arch
    if ($LASTEXITCODE -ne 0) { throw "Steam capture regression failed for $arch" }
  }
}
